  .corner-bar {
    position: fixed;
    top: 24px;
    right: 32px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 18px;
    font-family: inherit;
  }

  .corner-clock {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 1rem;
    color: #111;
    white-space: nowrap;
  }
  .corner-clock__slash { color: #888; }

  .corner-menu { position: relative; }
  .corner-menu__pill {
    display: flex;
    align-items: center;
    gap: 9px;
    background: #111;
    border: none;
    border-radius: 999px;
    padding: 5px 18px 5px 6px;
    cursor: pointer;
    transition: background 0.25s ease;
  }
  .corner-menu__pill:hover { background: #000; }
  .corner-menu__icon {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: #3a3a3a;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
  }
  .corner-menu__icon span {
    display: block;
    width: 12px;
    height: 1.5px;
    background: #fff;
    border-radius: 2px;
    transition: transform 0.25s ease, opacity 0.2s ease;
  }
  .corner-menu__label {
    color: #fff;
    font-size: 0.9rem;
    line-height: 1;
  }
  .corner-menu__list {
    list-style: none;
    margin: 8px 0 0;
    padding: 6px;
    background: #111;
    border-radius: 14px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    position: absolute;
    right: 0;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s;
  }
  .corner-menu.is-open .corner-menu__list {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }
  .corner-menu__list a {
    display: block;
    padding: 8px 16px;
    color: #fff;
    text-decoration: none;
    border-radius: 10px;
    font-size: 0.9rem;
    white-space: nowrap;
    transition: background 0.2s ease;
  }
  .corner-menu__list a:hover { background: #2a2a2a; }
  .corner-menu.is-open .corner-menu__icon span:nth-child(1) { transform: translateY(4.5px) rotate(45deg); }
  .corner-menu.is-open .corner-menu__icon span:nth-child(2) { opacity: 0; }
  .corner-menu.is-open .corner-menu__icon span:nth-child(3) { transform: translateY(-4.5px) rotate(-45deg); }

  @media (max-width: 640px) {
    .corner-bar { top: 16px; right: 16px; gap: 10px; }
    .corner-clock { font-size: 0.8rem; }
  }

